sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.cc-dashboard {
    width: 120%;
    padding: 26px 100px;
    box-sizing: border-box;
    font-family: "Segoe UI", Arial, sans-serif;
}


/* =========================
   WELCOME BANNER
   ========================= */

.cc-welcome {
    min-height: 126px;
    display: flex;
    align-items: center;
    padding: 26px 34px;
    box-sizing: border-box;

    background: linear-gradient(135deg, #172a63 0%, #1769d5 100%);
    border-radius: 14px;

    color: #ffffff;

    box-shadow: 0 8px 22px rgba(12, 45, 95, 0.16);
}

.cc-welcome h1 {
    margin: 0;
    font-size: 27px;
    font-weight: 700;
    line-height: 1.25;
    letter-spacing: -0.3px;
}

.cc-welcome p {
    margin: 9px 0 0 0;
    font-size: 14px;
    line-height: 2.0;
    color: #e1ecff;
}


/* =========================
   STATISTICS AREA
   ========================= */

.cc-stats {
    margin-top: 24px;
    margin-left: -7px;
    margin-right: -7px;
}


/* Remove Bootstrap column spacing issues */

.cc-stats > div {
    padding-left: 7px;
    padding-right: 7px;
}


/* =========================
   STAT CARD
   ========================= */

.cc-stat-card {
    min-height: 158px;
    padding: 22px 18px;
    box-sizing: border-box;

    background: #ffffff;
    border: 1px solid #e4e9f0;
    border-radius: 12px;

    text-align: center;

    box-shadow: 0 4px 14px rgba(20, 45, 80, 0.07);

    transition:
        transform 0.18s ease,
        box-shadow 0.18s ease,
        border-color 0.18s ease;
}

.cc-stat-card:hover {
    transform: translateY(-3px);
    border-color: #cdd9e8;
    box-shadow: 0 9px 22px rgba(20, 45, 80, 0.11);
}


/* =========================
   STAT ICON
   ========================= */

.cc-stat-icon {
    width: 42px;
    height: 42px;

    margin: 0 auto 12px auto;

    display: flex;
    align-items: center;
    justify-content: center;

    border-radius: 10px;

    background: #e8f2ff;

    font-size: 21px;
}


/* =========================
   NUMBER
   ========================= */

.cc-stat-card h3 {
    margin: 0;

    color: #172a4d;

    font-size: 26px;
    font-weight: 700;
    line-height: 1.2;
}


/* =========================
   LABEL
   ========================= */

.cc-stat-card p {
    margin: 7px 0 0 0;

    color: #6d7d91;

    font-size: 12px;
    font-weight: 500;
}


/* =========================
   RESPONSIVE
   ========================= */

@media (max-width: 992px) {

    .cc-dashboard {
        padding: 20px;
    }

    .cc-welcome {
        padding: 24px;
    }

    .cc-welcome h1 {
        font-size: 24px;
    }

    .cc-stat-card {
        margin-bottom: 14px;
    }
}


@media (max-width: 600px) {

    .cc-dashboard {
        padding: 15px;
    }

    .cc-welcome {
        min-height: 110px;
        padding: 20px;
    }

    .cc-welcome h1 {
        font-size: 21px;
    }

    .cc-welcome p {
        font-size: 12px;
    }
}

sp_widget.script:
(function() {

    /*
     * =========================================
     * CAMPUS CONNECT HOME
     * DYNAMIC DASHBOARD COUNTS
     * =========================================
     *
     * 1. Upcoming Events
     * 2. My Registrations
     * 3. My Teams
     * 4. Mentor Posts
     *
     * All counts are fetched from ServiceNow
     * database records.
     */


    /*
     * =========================================
     * INITIALIZE COUNTS
     * =========================================
     */

    data.upcomingEvents = 0;
    data.myRegistrations = 0;
    data.myTeams = 0;
    data.mentorPosts = 0;


    /*
     * =========================================
     * CURRENT LOGGED-IN USER
     * =========================================
     */

    var currentUser = gs.getUserID();


    /*
     * =========================================
     * CURRENT DATE/TIME
     * =========================================
     *
     * IMPORTANT:
     * gs.nowDateTime() is not allowed in
     * scoped application x_snc_campus_con_0.
     *
     * Therefore we use GlideDateTime.
     */

    var currentDateTime =
        new GlideDateTime();

    var currentDateTimeValue =
        currentDateTime.getDisplayValue();


    /*
     * =========================================
     * 1. UPCOMING EVENTS
     * =========================================
     *
     * Count only:
     *
     * Verification Status = Verified
     * AND
     * Event Date >= Current Date/Time
     *
     * This prevents rejected/pending/past events
     * from being counted.
     */

    var events =
        new GlideAggregate(
            'x_snc_campus_con_0_events'
        );


    events.addQuery(
        'verification_status',
        'verified'
    );


    events.addQuery(
        'event_date',
        '>=',
        currentDateTimeValue
    );


    events.addAggregate(
        'COUNT'
    );


    events.query();


    if (events.next()) {

        data.upcomingEvents =
            parseInt(
                events.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;

    }


    /*
     * =========================================
     * 2. MY REGISTRATIONS
     * =========================================
     *
     * Count registrations belonging to
     * the currently logged-in student.
     */

    if (currentUser) {

        var registrations =
            new GlideAggregate(
                'x_snc_campus_con_0_registrations'
            );


        registrations.addQuery(
            'student',
            currentUser
        );


        registrations.addAggregate(
            'COUNT'
        );


        registrations.query();


        if (registrations.next()) {

            data.myRegistrations =
                parseInt(
                    registrations.getAggregate(
                        'COUNT'
                    ),
                    10
                ) || 0;

        }

    }


    /*
     * =========================================
     * 3. MY TEAMS
     * =========================================
     *
     * A team is counted for the current user
     * when:
     *
     * A. Current user is Team Lead
     *
     * OR
     *
     * B. Current user is an Accepted Team Member
     *
     * Duplicate teams are counted only once.
     */

    var myTeamIds = {};


    /*
     * -----------------------------------------
     * A. TEAMS WHERE USER IS TEAM LEAD
     * -----------------------------------------
     */

    if (currentUser) {

        var leadTeams =
            new GlideRecord(
                'x_snc_campus_con_0_teams'
            );


        leadTeams.addQuery(
            'team_lead',
            currentUser
        );


        leadTeams.query();


        while (
            leadTeams.next()
        ) {

            myTeamIds[
                leadTeams.getUniqueValue()
            ] = true;

        }

    }


    /*
     * -----------------------------------------
     * B. TEAMS WHERE USER IS ACCEPTED MEMBER
     * -----------------------------------------
     */

    if (currentUser) {

        var teamMembers =
            new GlideRecord(
                'x_snc_campus_con_0_team_members'
            );


        teamMembers.addQuery(
            'student',
            currentUser
        );


        teamMembers.addQuery(
            'join_status',
            'Accepted'
        );


        teamMembers.query();


        while (
            teamMembers.next()
        ) {

            var memberTeamId =
                teamMembers.getValue(
                    'team'
                );


            if (memberTeamId) {

                myTeamIds[
                    memberTeamId
                ] = true;

            }

        }

    }


    /*
     * -----------------------------------------
     * COUNT UNIQUE TEAMS
     * -----------------------------------------
     */

    for (
        var teamId in myTeamIds
    ) {

        if (
            myTeamIds[teamId] === true
        ) {

            data.myTeams++;

        }

    }


    /*
     * =========================================
     * 4. MENTOR POSTS
     * =========================================
     *
     * Count all records in Mentor Connect.
     */

    var mentorPosts =
        new GlideAggregate(
            'x_snc_campus_con_0_mentor_connect'
        );


    mentorPosts.addAggregate(
        'COUNT'
    );


    mentorPosts.query();


    if (mentorPosts.next()) {

        data.mentorPosts =
            parseInt(
                mentorPosts.getAggregate(
                    'COUNT'
                ),
                10
            ) || 0;

    }


    /*
     * =========================================
     * OPTIONAL DEBUG INFORMATION
     * =========================================
     *
     * These values can help us verify the
     * dashboard during testing.
     */

    data.debug = {

        currentUser:
            currentUser,

        upcomingEvents:
            data.upcomingEvents,

        myRegistrations:
            data.myRegistrations,

        myTeams:
            data.myTeams,

        mentorPosts:
            data.mentorPosts

    };


})();
